   "titolo": "Francia, accuse alla polizia per ferite 'da guerra' su studenti durante le proteste scolastiche",
   "orig": "French police accused over war-like injuries to teenagers in school protests",
   "lead": "Avvocati e associazioni per i diritti umani in Francia denunciano che diversi adolescenti hanno subito ferite simili a quelle di guerra causate da armi della polizia durante le proteste nelle scuole, ora alla quarta settimana. Quattro minori sarebbero stati 'mutilati' da armi esplosive e un numero senza precedenti di giovani è stato trattenuto in custodia, alcuni denunciando di essere stati colpiti o insultati razzialmente. Centinaia di scuole superiori sono bloccate da studenti che chiedono la sostituzione di insegnanti assenti e la riparazione di edifici degradati. Lo riferisce The Guardian.",
   "more": [
    "In Francia le mobilitazioni studentesche nelle scuole superiori sono un fenomeno ricorrente, spesso legate a carenze di organico e cattive condizioni degli edifici, e talvolta sfociano in tensioni con le forze dell'ordine."
   ],
