   "lead": "Le nuove sanzioni statunitensi sul settore dell'aviazione stanno costringendo i cittadini iraniani a viaggi più lunghi e costosi, con la progressiva scomparsa delle rotte aeree internazionali verso e dall'Iran. Lo riferisce Al Jazeera.",
