   "lead": "Un tribunale del distretto di Korday, in Kazakistan, ha ordinato due mesi di custodia cautelare per il rapper russo Navai Bakirov, accusato di traffico di droga. L'arresto è avvenuto il 13 ottobre al confine tra Kirghizistan e Kazakistan. Il consolato russo ha chiesto chiarimenti alle autorità kazake sul caso.",
