   "titolo": "L'OMS chiede vigilanza dopo il secondo caso di Ebola in Kenya",
   "orig": "WHO urges vigilance after Kenya confirms second Ebola case",
   "lead": "L'Organizzazione Mondiale della Sanità continua a sostenere il Kenya nel contenimento dell'Ebola dopo che una seconda persona è risultata positiva al virus Bundibugyo, come riferito dal rappresentante dell'agenzia Onu nel paese. In Repubblica Democratica del Congo l'epidemia resta attiva con oltre 9.000 casi confermati e 4.410 decessi, cinque mesi dopo la dichiarazione ufficiale. Il Kenya ha dichiarato l'Ebola Bundibugyo una malattia epidemica grave, introducendo nuove regole su screening, isolamento, quarantena, tracciamento dei contatti e sepolture sicure.",
   "more": [
    "Il virus Ebola Bundibugyo è una delle specie del virus Ebola, meno letale rispetto ad altre varianti ma comunque in grado di causare gravi epidemie, trasmesso tra persone tramite contatto con fluidi corporei."
   ],
