   "orig": "Renovation of the Core Area of TAFA Art Block / Mix Architecture",
   "lead": "Lo studio Mix Architecture ha realizzato il progetto di rinnovamento del nucleo urbano adiacente all'Accademia di Belle Arti di Tianjin, in Cina, un'area rimasta a lungo trascurata nonostante la vicinanza al fiume Haihe e ai flussi turistici generati dal Tianjin Eye. Nel 2022 il governo del distretto di Hebei e l'Accademia avevano firmato un accordo per sviluppare congiuntamente il campus e l'area circostante, dando origine al progetto «TAFA Art Block», pensato come un distretto d'arte aperto che integra quartiere, campus e territorio. Lo riferisce ArchDaily.",
