   "lead": "Nella partita inaugurale della Rugby League World Cup 2026, disputata all'Allianz Stadium, l'Australia ha battuto la Nuova Zelanda per 24-22, con Jack Bostock autore di una tripletta di mete al suo debutto. ABC News Australia definisce l'incontro un ricordo dei giorni d'oro del rugby league nei test match, mentre il Guardian ne ha seguito lo svolgimento minuto per minuto, citando anche la prestazione dell'arbitro Adam Gee. Il torneo 2026 comprende dieci squadre.",
