   "id": "z61d34f1b",
   "sez": "musica",
   "titolo": "Olivia Rodrigo e Chappell Roan si sfidano nel videoclip di «Expectations»",
   "orig": "Olivia Rodrigo and Chappell Roan Compete on David Byrne’s Gameshow in “Expectations” Video",
   "lead": "Olivia Rodrigo e Chappell Roan compaiono insieme in un game show condotto da David Byrne nel video del remix di «Expectations», brano tratto da «You Seem Pretty Sad for a Girl So in Love». Secondo Billboard, le due pop star hanno raccontato a Zane Lowe l'ispirazione dietro la collaborazione, incluse le storie sentimentali che hanno ispirato il verso scritto da Roan, che ha detto di amare «rendere le cose un po' gay».",
   "more": [
    "Olivia Rodrigo e Chappell Roan sono due delle voci più seguite del pop statunitense contemporaneo, note rispettivamente per testi confessionali sulle relazioni adolescenziali e per un'estetica audace e dichiaratamente queer."
   ],
