   "lead": "Orizzonte Scuola affronta il caso di un viaggio d'istruzione già deliberato dal consiglio di classe e comunicato alle famiglie, che rischia di non partire perché nessun docente si rende disponibile ad accompagnare gli studenti. L'articolo analizza cosa può fare in questi casi il dirigente scolastico per risolvere la situazione. Lo riferisce Orizzonte Scuola.",
