   "lead": "Un'analisi rigorosa ha confermato le buone prestazioni dello scudo termico della missione Artemis II della NASA, che ha portato quattro astronauti in orbita lunare e li ha riportati sani e salvi sulla Terra, gettando le basi per i futuri voli con equipaggio verso la superficie lunare. Lo riferisce Phys.org.",
