   "titolo": "L'AIEA completa una missione di protezione fisica nucleare in Pakistan",
   "orig": "IAEA Completes International Physical Protection Advisory Service Mission in Pakistan",
   "lead": "L'Agenzia internazionale per l'energia atomica ha completato una missione di consulenza internazionale sulla protezione fisica (IPPAS) in Pakistan, nell'ambito del suo programma di assistenza ai paesi membri per la sicurezza dei materiali e degli impianti nucleari. Lo riferisce l'AIEA.",
   "more": [
    "Le missioni IPPAS dell'AIEA valutano i sistemi nazionali di protezione fisica di materiali e impianti nucleari, fornendo raccomandazioni per rafforzare la sicurezza contro furti o atti di sabotaggio."
   ],
