   "titolo": "I conti di Anthropic crescono, ma il settore tech affonda in Borsa",
   "orig": "Anthropic, corrono i conti. Ma il tech affonda in Borsa",
   "lead": "I conti di Anthropic, pubblicati a New York, mostrano risultati in crescita, ma non sono bastati a rassicurare i mercati tecnologici, che hanno continuato a scendere in Borsa. Per un settore caratterizzato da grandi promesse e pochi ritorni concreti, i dati dell'azienda sono stati la prima conferma attesa dagli investitori. La Borsa coreana ha perso il 7,6%, mentre a Milano Technoprobe è scesa di oltre il 10%, tra i timori legati al debito del 'neocloud'.",
   "more": [
    "Anthropic è una delle principali aziende di intelligenza artificiale, sviluppatrice del chatbot Claude; i suoi risultati finanziari sono osservati con attenzione dai mercati per valutare la sostenibilità degli investimenti miliardari nel settore dell'IA."
   ],
