   "lead": "La nazionale Under-20 della Guinea ha iniziato con una vittoria il torneo UFOA-A, competizione qualificante per la prossima Coppa d'Africa di categoria. Giovedì 15 ottobre a Bamako, in Mali, i giovani guineani si sono imposti per 1-0 sui padroni di casa maliani nella partita inaugurale del torneo, grazie a una rete siglata nel primo tempo da Keita.",
