   "orig": "I Indulged in Rare, 135-Year-Old Wine at This Sonoma Resort",
   "lead": "Un'autrice di Bon Appétit racconta la propria esperienza di degustazione di un raro vino con 135 anni di storia presso il Dawn Ranch, un resort nella regione vinicola della Sonoma, in California. Le cabine storiche della struttura e le imponenti sequoie che la circondano fanno da scenario a questa cena di alta cucina. Lo riferisce Bon Appétit.",
