   "id": "zdd8df5fb",
   "sez": "salute",
   "titolo": "Dosi frazionate di vaccino contro la febbre gialla per ottimizzare le scorte",
   "orig": "[Comment] Making every vial count: fractional dosing of yellow fever vaccine",
   "lead": "La febbre gialla resta un importante problema di sanità pubblica, ma la produzione del vaccino non può essere aumentata facilmente, rendendo necessario sfruttare al meglio le scorte esistenti. Durante le epidemie si è ricorso a dosi frazionate, generalmente un quinto di flaconcino, pratica sostenuta da evidenze di immunogenicità negli adulti e approvata dall'OMS. Recenti studi condotti nel 2023 e nel 2026 hanno chiarito se questa strategia sia efficace anche nei bambini. Lo riferisce The Lancet.",
   "more": [
    "La febbre gialla è una malattia virale trasmessa da zanzare, endemica in alcune aree tropicali di Africa e Sud America; la vaccinazione di routine nei bambini delle zone endemiche è una misura cardine di prevenzione, ma dipende dalla disponibilità di dosi."
   ],
