   "titolo": "Il progetto \"Migla\" vince il concorso per il padiglione e la piazza della stazione di Riga",
   "orig": "The 'Migla' ('Fog') proposal wins the design competition for the development of the Pavilion and Station Square - The Baltic Times",
   "lead": "Il progetto denominato \"Migla\" (che significa \"nebbia\") ha vinto il concorso di progettazione aperto per lo sviluppo del padiglione e della piazza della stazione in via Stacija 4, a Riga, capitale della Lettonia. La valutazione delle candidature presentate al concorso si è conclusa con questa decisione. Lo riferisce The Baltic Times.",
