   "titolo": "In Nepal, la valle della Trishuli cerca la via del ritorno alla vita dopo lo \"tsunami delle montagne\"",
   "orig": "Au Népal, la vallée de la Trishuli, dévastée par le « tsunami des montagnes », cherche le chemin du retour à la vie",
   "lead": "Il 26 agosto scorso, una frana che ha trascinato con sé un ghiacciaio ha provocato un'esondazione devastante e mortale nella valle della Trishuli, in Nepal. Più di 5.000 persone non sono ancora state ritrovate, e molti dei superstiti soffrono di quello che viene descritto come il senso di colpa di chi è sopravvissuto. La valle oggi cerca lentamente di ricostruire una vita normale dopo la catastrofe. Lo riferisce Le Monde.",
   "more": [
    "La valle della Trishuli si trova in Nepal, ai piedi della catena himalayana, zona soggetta a rischi legati allo scioglimento dei ghiacciai e alle frane; eventi di questo tipo, aggravati dai cambiamenti climatici, possono generare piene improvvise e distruttive note come \"tsunami di montagna\"."
   ],
