   "id": "z79971592",
   "sez": "salute",
   "titolo": "Accorciare la terapia per accelerare l'eliminazione dell'epatite C",
   "orig": "[Comment] Shortening treatment to accelerate hepatitis C elimination",
   "lead": "I trattamenti antivirali orali diretti per l'epatite C hanno trasformato la gestione clinica della malattia e aperto la strada alla sua eliminazione. Il primo regime pan-genotipico a dose fissa, sofosbuvir-velpatasvir, è stato approvato nel 2016, seguito nel 2017 dalla combinazione glecaprevir-pibrentasvir. Entrambi i trattamenti di prima linea raccomandati condividono alta efficacia, buona tollerabilità e somministrazione orale giornaliera, ma differiscono per numero di pillole, durata della terapia e disponibilità: il primo si prescrive per 12 settimane, con una formulazione generica disponibile. Lo riferisce The Lancet.",
   "more": [
    "L'epatite C è un'infezione virale del fegato che può portare a cirrosi e tumore se non trattata; i farmaci antivirali ad azione diretta hanno reso possibile la cura della malattia in poche settimane, ponendo le basi per l'obiettivo globale della sua eliminazione come problema di sanità pubblica."
   ],
