   "lead": "Il governo dello stato australiano di Victoria ha annunciato un accordo quinquennale per portare le gare delle Supercars sul circuito di Phillip Island, con l'obiettivo di compensare una perdita stimata in 80 milioni di dollari causata dall'addio della MotoGP dal circuito. Lo riferisce ABC News Australia.",
