   "lead": "Un'opera d'arte proveniente da Grenada, un assemblaggio di carta fatto a mano composto da due pannelli, è entrata nella collezione permanente del Museo d'Arte delle Americhe dell'Organizzazione degli Stati Americani (OAS). L'opera rende omaggio alle donne che hanno sostenuto le famiglie e le comunità grenadine, custodendo al tempo stesso conoscenze e tradizioni culturali ancestrali. Lo riferisce NOW Grenada.",
