   "titolo": "Manovra 2027 da 23,5 miliardi: 5 miliardi dalle banche, niente taglio dell'Irpef",
   "orig": "Manovra, banche: contributo non negoziato",
   "lead": "Il governo italiano si prepara a varare una legge di bilancio per il 2027 da circa 23,5 miliardi di euro, la seconda più leggera della legislatura, che prevede un prelievo di 5 miliardi dal comparto bancario e assicurativo senza che l'onere sia stato negoziato con gli istituti, colti di sorpresa dalla misura. La priorità della manovra va al sostegno del potere d'acquisto delle famiglie più fragili, mentre resta fuori il taglio dell'Irpef più volte annunciato nei mesi scorsi; una parte della copertura arriva dai margini di flessibilità concessi da Bruxelles.",
