  "istanbulalluvione": "Il qatariota Al Jazeera e la britannica Sky News si concentrano sul bilancio umano e sui soccorsi; le turche Turkish Minute e Bianet English raccontano rispettivamente gli episodi più mediatici e le cause strutturali del dissesto urbano.",
  "indonesiahaze": "La britannica BBC raccoglie le testimonianze degli abitanti sotto la coltre di fumo; l'hongkonghese SCMP e la vietnamita VnExpress seguono la polemica sul governatore fotografato a Singapore; il giapponese Japan Times dà risalto alle indagini di Singapore sulle aziende responsabili; l'indonesiana Antara e la neozelandese RNZ Pacific restano sui disagi concreti per i trasporti e la salute.",
  "elninoglobale": "La sudafricana Daily Maverick riporta l'allarme diretto del governo di Pretoria; la britannica Guardian guarda alle soluzioni agricole possibili; la francese Euronews documenta l'impatto già concreto sull'Europa; l'americana Science si concentra sulle conseguenze ecologiche globali; la greca Keep Talking Greece segnala l'allerta rossa nazionale.",
  "manovrabanche": "ANSA e Rai News danno risalto alla sorpresa delle banche per un prelievo non negoziato; la Repubblica nota l'assenza del taglio Irpef definendo la manovra «piccola piccola»; Il Sole 24 Ore si concentra sul sostegno alle famiglie fragili; Il Messaggero sulle coperture concesse da Bruxelles.",
  "carocarburanti": "Rai News inquadra la protesta nel suo complesso; la Repubblica si concentra sulla minaccia di blocco nazionale e sulla convocazione ministeriale; Il Sole 24 Ore sui dettagli organizzativi dello sciopero in Sicilia e Calabria.",
  "zacharia": "La britannica BBC apre la vicenda sulle credenziali mancanti; la canadese CBC segue la difesa della portavoce; Straits Times e NZ Herald riportano le sue dichiarazioni sulla Cina; la hongkonghese SCMP ne nota l'imprecisione; la cipriota Cyprus Mail chiude con l'ammissione finale.",
  "letteresospette": "La britannica BBC si concentra sugli Stati coinvolti; l'americana NPR dà più risalto alle indagini federali in corso e alla natura delle sostanze rinvenute.",
  "hormuz": "Il resoconto si basa sull'analisi di BBC Verify, che collega l'aumento record degli attacchi alle navi al clima di tensione nello Stretto di Hormuz legato alla guerra in corso tra Stati Uniti e Iran.",
  "myanmarasean": "Il resoconto, dell'emittente qatariota Al Jazeera, mette in luce sia il successo diplomatico regionale del generale sia le critiche di chi teme che l'apertura dell'ASEAN legittimi un esercito ancora in guerra con parte della popolazione civile.",
  "madurotortura": "Il resoconto, del britannico Guardian, si concentra sulla scena dell'udienza e sulla reazione diretta di Maduro, che respinge come false le nuove accuse di tortura contenute nell'imputazione riscritta.",
  "teslaroadster": "Le testate italiane Il Post e Repubblica si concentrano sullo spettacolo della presentazione e sui dati tecnici; le tedesche Spiegel e FAZ guardano rispettivamente alla dichiarazione sulla guida umana e ai limiti della variante a razzo; l'austriaca Der Standard nota i ritardi di produzione; l'argentina La Nación riprende la cautela espressa da Musk stesso.",
  "z4b703a8b": "ANSA sottolinea la rimonta bianconera firmata Kolo Muani, mentre Rai News evidenzia la superiorità del Milan nonostante l'inferiorità numerica.",
  "zfc56037c": "BBC News mette in evidenza come solo un inceppamento dell'arma abbia impedito l'attacco.",
  "zb5765090": "The Guardian denuncia un uso sproporzionato della forza da parte della polizia contro i minori.",
  "z0eadb11a": "The Guardian riporta i dettagli ufficiali forniti dalle autorità francesi sul numero e la gravità dei feriti.",
